import { ensureElement } from "../utils/utils";
import { FormOrder } from "./FormOrder";
// Класс контактных данных покупателя
export class FormContact extends FormOrder {
    constructor(container, events) {
        super(container, events);
        this.container = container;
        this.events = events;
        this._email = ensureElement('.form__input[name="email"]', this.container);
        this._numberPhone = ensureElement('.form__input[name="phone"]', this.container);
    }
    // Устанавливает электронную почту покупателя
    set email(value) {
        this.setText(this._email, value);
    }
    // Устанавливает номер телефона покупателя
    set phone(value) {
        this.setText(this._numberPhone, value);
    }
}
