import { Component } from './base/Component';
import { ensureElement } from '../utils/utils';
// Класс корзины с товарами
export class Page extends Component {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._amount = ensureElement('.header__basket-counter', this.container);
        this._listProducts = ensureElement('.gallery', this.container);
        this._wrapper = ensureElement('.page__wrapper', this.container);
        this._basket = ensureElement('.header__basket', this.container);
        this._basket.addEventListener('click', () => {
            this.events.emit('basket:open');
        });
    }
    // Устанавливает список товаров в ларьке
    set listProducts(products) {
        this._listProducts.replaceChildren(...products);
    }
    // Устанавливает количество товаров добавленых в корзину
    set amountProducts(total) {
        this.setText(this._amount, total);
    }
    // Устанавливает состояние страници на заблокировано/разблокировано
    set lockPage(state) {
        this.toggleClass(this._wrapper, 'page__wrapper_locked', state);
    }
}
